-- 2026-10-12, owner: (a) WhistlePig Beyond Bonded Bourbon read as 100 proof (BiB by law; inserted by the writer, see out/wp3), (b) seven more Hard Truth seeded ages the maker never states -> NAS, (c) maker rows with a stated proof are status 'confirmed' (the admin review queue is status = 'draft').
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"WhistlePig FarmStock Beyond Bonded Bourbon","rar":"limited","f":"WhistlePig","x":"FarmStock Beyond Bonded Bourbon","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":false,"al2":["WhistlePig Beyond Bonded Bourbon"],"img":"https://cdn.prod.website-files.com/61f27a53fd39a15d7eed0e9c/63d124229c5e189fedca1de7_Frame%205.png","u":"https://www.whistlepigwhiskey.com/whiskeys/beyond-bonded-bourbon","pr":"WhistlePig","mk":"12abd2bb-515a-4ea9-9bcb-2f2c07a0051a"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
update cellar.products set age_years = null, age_label = 'NAS', nas = true where id in ('56769933-cead-4b66-8191-44c430bba101','2acdd869-0951-4527-86b6-8f37b6dc0507','e6805830-5236-43cc-a67e-408c122fd892','3eea425d-ff79-4418-aa95-0f27e7ae7577','3997380e-18c4-4e84-8d70-fe29cdcb7650','ab97fdfa-09f5-40ec-a376-fe450aaf01b8','e712c9ad-090d-46b4-83c5-6547e892ed5d') and facts_verified_at is null;
update cellar.products set status = 'confirmed' where type = 'bourbon' and source = 'maker' and status = 'draft' and proof is not null and merged_into is null;
